108	// openAllowedRoot finds the allowed root directory that contains dst and returns
109	// an os.Root handle along with the relative path within that root.
110	// Allowed directories: repo worktree root, user home, system temp dir.
111	// dst is resolved through symlinks before matching to handle macOS /var → /private/var.
112	func openAllowedRoot(dst string) (*os.Root, string, error) {
113		allowed := allowedRootDirs()
114	
115		// Resolve the directory portion of dst through symlinks so that e.g.
116		// /var/folders/... matches /private/var/folders/... on macOS.
117		// Only the parent directory is resolved; the final component may not exist yet.
118		resolvedDst := dst
119		if r, err := filepath.EvalSymlinks(filepath.Dir(dst)); err == nil {
120			resolvedDst = filepath.Join(r, filepath.Base(dst))
121		}
122	
123		for _, dir := range allowed {
124			if !paths.IsSubpath(dir, resolvedDst) {
125				continue
126			}
127			rel, err := filepath.Rel(dir, resolvedDst)
128			if err != nil {
129				continue
130			}
131			root, err := os.OpenRoot(dir)
132			if err != nil {
133				return nil, "", fmt.Errorf("openAllowedRoot: failed to open root %q: %w", dir, err)
134			}
135			return root, rel, nil
136		}
137	
138		return nil, "", fmt.Errorf("openAllowedRoot: dst %q is outside allowed directories", dst)
139	}
140	
141	// allowedRootDirs returns the list of directories that copyFile may write to.
142	// Directories are resolved through symlinks so they match resolved dst paths.
143	func allowedRootDirs() []string {
144		allowed := make([]string, 0, 3)
145	
146		if repoRoot, err := paths.WorktreeRoot(context.Background()); err == nil {
147			allowed = appendResolved(allowed, repoRoot)
148		}
149		if home, err := os.UserHomeDir(); err == nil {
150			allowed = appendResolved(allowed, home)
151		}
152		if tmpDir := os.TempDir(); tmpDir != "" {
153			allowed = appendResolved(allowed, tmpDir)
154		}
155	
156		return allowed
157	}
158	
159	// appendResolved appends dir to the list after resolving symlinks.
160	// Falls back to the original path if symlink resolution fails.
161	func appendResolved(dirs []string, dir string) []string {
162		if resolved, err := filepath.EvalSymlinks(dir); err == nil {
163			return append(dirs, resolved)
164		}
165		return append(dirs, dir)
166	}

